-- 1) Source (992 reuses Pass-123 sources 3139/3140)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3141, 'https://uchile.cl/postgrado-y-postitulo/departamento-de-postgrado-y-postitulo/ayudas-y-financiamientos/beca-de-doctorado-uchile', 'Beca de Doctorado de la Universidad de Chile | Universidad de Chile (official)', 'uchile.cl', 'scholarship', now(), true, true, now());

-- 2) 710 uplift (rel 9 -> 10): strip importer minima; normalise award/deadline; add fetched 2026-cycle facts.
UPDATE scholarships SET description = 'Chile funds outward mobility rather than inward, and the University of Chile is a clear example: the entrance scholarships it lists for foreigners are closed to an applicant from Uzbekistan (the OAS academic scholarship is for nationals of OAS member states, the Nelson Mandela master programme covers only Angola, Mozambique and South Africa, and the AGCID schemes are built for Latin America). What exists is in-programme support once a student is enrolled. The flagship is the Beca de Doctorado de la Universidad de Chile (official 2026 call page fetched for this update): CLP 900,000 a month for twelve months (March 2026 to February 2027) PLUS full exemption of the university tuition (arancel, excluding the enrolment fee matricula), for regular first- or second-year doctoral students who applied to the last ANID national doctoral competition and hold no other funding. It is renewable on certified progress, but the holder must reapply to ANID every year and the university benefit ceases automatically on the first ANID payment, freeing the funds for the next call - so it tops up a student already inside, it does not open the door. Entry is by graduate-school nomination (up to two valid applications per doctoral programme) and the programme must normally hold CNA accreditation of six years or more (recently created programmes and documented improvement-plan cases excepted). Beyond that, the faculties run tuition rebates for doctoral and master students worth 50, 75, 90 or 100 per cent of the annual programme tuition, and several faculty schemes are explicitly open to Chilean and foreign students alike, such as the SYLFF-UChile programme for the master in management and public policy (tuition, matricula and maintenance; December application). The practical conclusion for a student from Uzbekistan is unchanged: the University of Chile is a pay-first destination - the doctoral programme in mining engineering, for example, published tuition of 800 UF (about USD 32,000) when this record was last fully read, plus an annual matricula. The genuinely open Chilean door for a prospective doctoral applicant from Uzbekistan is the national ANID competition (record 990), not this university scheme.', requirements = 'From the fetched 2026 call page. For the Beca de Doctorado de la Universidad de Chile: (1) be a regular first- or second-year student in a University of Chile doctoral programme; (2) have applied to the last ANID Beca de Doctorado Nacional competition; (3) hold no other source of funding, national or international; (4) file the simple sworn declaration of no convictions under laws 21.369, 20.066 or 20.609 and not be in the national alimony-debtor registry (Ley 21.389); (5) be enrolled in a programme with CNA accreditation of 6 years or more at application (programmes up to 3 years old may apply unaccredited; under-6-year programmes only exceptionally with a documented improvement plan). Your graduate school pre-selects and nominates at most two valid applications per programme; the final selection is by the university committee (with a gender-balance rule: no more than 50 per cent of awards to registered males where enough admissible applications from women are presented). Holders must keep making timely progress, certified by the graduate school director, and must apply to ANID annually; winning ANID ends this benefit automatically at the first ANID payment. For the faculty tuition rebates, apply within each faculty window with fees and any debt regularised. For SYLFF-UChile, be a professional admitted to the master in management and public policy and apply in December. The OAS, Nelson Mandela and AGCID entrance routes remain closed to applicants from Uzbekistan.', deadline = 'Annual internal competition, timed to the Chilean academic year. The fetched 2026 Beca de Doctorado call opened on 15 January 2026; graduate schools nominated up to two candidates per programme and nominated students submitted online by 18:00 on 6 March 2026; preliminary results came at the end of April 2026. The 2027 edition is not yet published - watch the official page around January. Faculty tuition rebates have their own per-faculty windows, and SYLFF-UChile applies in December.', deadline_date = NULL, deadline_type = 'not_published', application_status = 'upcoming', recurrence = 'annual', expected_opening_period = 'Mid-January (2026 call: 15 January)', expected_deadline_period = 'Early March via graduate-school nomination (2026 call: 6 March 18:00)', rounds = '[{"name": "Beca de Doctorado UChile 2026 (closed)", "status": "Opened 15 Jan 2026; graduate schools nominated up to 2 applicants per programme; online submissions to 6 Mar 2026 18:00; preliminary results end-Apr 2026; CLP 900,000/month Mar 2026-Feb 2027 plus full arancel exemption (matricula excluded).", "deadline_date": null}, {"name": "Faculty tuition rebates and SYLFF-UChile", "status": "Faculties publish their own rebate windows (50, 75, 90 or 100 per cent of annual programme tuition, fees regularised); SYLFF-UChile for the master in management and public policy applies in December.", "deadline_date": null}]', eligible_countries = '["Students already enrolled as regular students at the Universidad de Chile (in-programme benefits; several faculty schemes expressly include foreign students). Entrance scholarship routes for foreigners published by the university (OAS, Nelson Mandela, AGCID) are closed to Uzbekistan."]', award_amount = NULL, award_currency = 'CLP', award_period = 'month', award_basis = 'variable', funding_type = 'In-programme institutional support: doctoral stipend CLP 900,000/month for 12 months (2026 cycle) plus full tuition (arancel) exemption excluding matricula; faculty tuition rebates of 50-100 per cent alongside', tuition_coverage = 'The Beca de Doctorado carries full exemption of the programme arancel for the award year (the enrolment fee matricula is excluded and must be paid; the graduate school certifies the exemption), on top of the monthly stipend. Faculty rebates separately deduct 50, 75, 90 or 100 per cent of the annual programme tuition from the fee account. No entrance tuition scholarship for a prospective applicant from Uzbekistan is published.', living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, required_documents = '["2026 matricula payment proof in the mandatory format (formato N 7)", "Cover letter stating the intention to obtain the beca", "Curriculum Vitae in ANID format", "Grade transcripts (undergraduate and/or postgraduate as applicable)", "Two recommendation letters sent independently by the recommenders", "Proof of application to the ANID Beca de Doctorado Nacional (only the accepted document types)", "Letter from the graduate school certifying full doctoral tuition beca on award (official format)", "Simple sworn declaration (no convictions under laws 21.369/20.066/20.609; not in the alimony-debtor registry)", "Improvement plan with significant progress (only for programmes accredited under 6 years)"]', english_requirements = 'The benefits set no separate English score; the language requirement of the chosen programme applies, and most University of Chile postgraduate teaching is in Spanish.', min_gpa = NULL, min_ielts = NULL, verification_status = 'verified', source_reliability = 10, last_verified_at = now(), last_updated_at = now(), notes = 'Enrichment Batch 30 (2026-10-28) uplift from rel 9 to rel 10. First-hand fetch today: the official Beca de Doctorado UChile call page, both chunks (new source 3141) - CLP 900,000/month x 12 (Mar 2026-Feb 2027) PLUS full arancel exemption excluding matricula (new detail vs the 2026-10-25 read); renewal on certified progress with mandatory annual ANID application; automatic cessation at the first ANID payment; five numbered requirements including the CNA 6+-year accreditation rule (new-programme and improvement-plan exceptions) and the sworn-declaration laws; graduate-school nomination capped at 2 per programme; 50 per cent gender-balance rule; 2026 window opened 15 Jan 2026, submissions to 6 Mar 2026 18:00, preliminary results end-Apr 2026; documents list 01-09. Repairs in this uplift: importer min_gpa 3.3 / min_ielts 6.5 removed (the row own english_requirements already said no separate score); award normalised from a single-cycle fixed 900000 to NULL CLP month variable (multi-component record: cycle-valued stipend + tuition exemption + percentage rebates); deadline normalised from type annual/status not_announced/empty rounds to not_published/upcoming with the fetched 2026 cycle in rounds; empty-string accommodation cleared; eligible_countries rewritten honestly; us 274 resynced (availability Yes normalised). Retained from the 2026-10-25 first-hand reads (not refetched): faculty rebates 50/75/90/100 per cent, SYLFF-UChile December window and coverage, OAS/Nelson Mandela/AGCID closures for Uzbekistan, and the mining-doctorate 800 UF example (now date-qualified). First source links added for this row (it had none). Cross-reference: ANID Doctorado Nacional = record 990, which this beca expressly complements. Rel 10; university 303 retained.' WHERE id = 710;

-- 3) NEW 992 Young Researchers - University of Ljubljana (employment model)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (992, 'Young Researchers (Mladi raziskovalci) - University of Ljubljana', 'University of Ljubljana member institutions (Slovenian young-researcher system)', 'Slovenia', 'Full Tuition + Stipend', 0, 'Positions are published as job tenders. The first call is published every year on 15 March (2026: published 16 March, deadline 8 May 2026, 23:59), and a second call may follow (2026: published 1 September, deadline 10 September 2026, 23:59); both 2026 calls are completed. Watch the official UL tender pages each spring.', '["PhD"]', '["All Majors"]', NULL, NULL, false, true, 'Slovenia funds most of its doctorates through employment, not scholarships, and this record documents that route at the University of Ljubljana from the university''s official pages. Young researchers are doctoral students employed full-time in research programmes at UL member institutions (faculties, academies and institutes): the employing member covers the doctoral tuition fees in full and provides the funds and material resources for the research. It is a fixed-term employment contract - four years, or three years if you start as a second-year doctoral student - not a grant. The official FAQ puts the salary in the 22nd salary grade, equating to 2,332.62 EUR gross per month on the fetched page (with the public-sector elimination of salary imbalances being completed by 2028), plus reimbursed lunch and travel expenses. Positions are attached to a named mentor and research programme and are published as job tenders: the first call appears every year on 15 March (in 2026 it was published on 16 March with an 8 May deadline), and a second call may follow in September (2026: 1 September to 10 September; both 2026 calls are completed). You apply twice in parallel - to the young-researcher tender for a specific mentor, and separately for doctoral enrolment through the national eVS portal - because without enrolment the employment contract cannot be signed. The system is a national one (young researchers must be entered in the ARIS register of researchers) and analogous positions exist at other Slovenian research organisations, but this record asserts only the University of Ljubljana route as fetched. The application machinery explicitly provides for candidates who completed their studies outside UL and abroad, who attach the diploma supplement and their institution''s official grade scale.', 'From the fetched UL page. To apply: at most 4 years may have passed since completing your second-cycle (master-level) programme - for the 2026 call, completion from 1 January 2022 onward, or still completing it - with extensions for parental leave or continuous health-related absence over 6 months; fulfil the conditions for election to the title of assistant, including an average grade of at least 8.00 across the second-cycle programme and the final thesis (only second-level numerically graded obligations count; pass-only obligations are excluded; the 8.00 is on the Slovenian scale, so it is recorded here in text, not as a generic min_gpa); meet any further conditions in the specific job description; have not completed a doctorate and never have been employed as a young researcher. There is no age restriction. To be employed you must enrol in the 1st or 2nd year of a UL doctoral programme for the coming academic year, hold the assistant habilitation title, be in the ARIS register of researchers on the employment date, belong to the same research programme as your supervisor, take full-time employment at UL, and keep student status throughout. Apply to each mentor separately (register separately per application; mentors are notified of all your applications); prior contact with the mentor is not required for the application itself. Corrections to an application must be requested at least one business day before the deadline.', 'https://www.uni-lj.si/en/research/young-researchers', '["All - no nationality condition appears on the fetched pages, and the application FAQ expressly provides for candidates whose degrees were completed outside the University of Ljubljana and abroad (diploma supplement plus official grade scale); doctoral enrolment and ARIS-register entry still apply"]', 'Full-time fixed-term employment contract (4 years; 3 if entering the 2nd doctoral year) at a UL member institution; salary grade 22 = 2,332.62 EUR gross/month on the fetched page, plus reimbursed lunch and travel expenses; doctoral tuition fully covered and research funds provided by the employing member', 'Fully covered by the employing UL member institution for the duration of the young-researcher employment', NULL, NULL, NULL, NULL, 'No English-test requirement appears on the fetched pages; programme- and mentor-level language conditions were not verified for this record - check the specific doctoral programme and tender.', '["Application to the Call to Tender for Young Researcher Candidates (UL online form, separately for each mentor)", "Diploma certificate and diploma supplement (or certificate of completion / official transcript if the diploma is not yet issued)", "Official grade scale of the awarding institution (required when studies were completed outside UL or abroad)", "Parallel application for doctoral enrolment via the national eVS portal (programme deadlines differ)"]', 'https://www.uni-lj.si/en/research/young-researchers', NULL, NULL, 'not_published', NULL, NULL, '[{"name": "First call 2026 (closed)", "status": "Published 16 Mar 2026; application deadline 8 May 2026 23:59; type: job application; status completed.", "deadline_date": null}, {"name": "Second call 2026 (closed)", "status": "Published 1 Sep 2026; application deadline 10 Sep 2026 23:59; type: job application; status completed.", "deadline_date": null}, {"name": "Annual pattern", "status": "The first call is published every year on 15 March (or the next working day); a second call may follow when positions remain. Employment starts with enrolment in the 1st or 2nd doctoral year.", "deadline_date": null}]', 'annual', '15 March (first call, every year)', 'Early May (first call); a second call may follow in September', 'upcoming', now(), now(), 'verified', 10, 'https://www.uni-lj.si/en/research/young-researchers', 'Enrichment Batch 30 (2026-10-28) candidate add - the Slovenian young-researcher route documented under its real identity after Pass 123 retired the invented-name 404 that gestured at Ljubljana. Evidence, all first-hand and UL-official: Young researchers page chunk 0 (read in Pass 123, source 3139: employed doctoral students in UL member research programmes, tuition fully covered, employer provides research resources; 2026 tenders published 2026-03-16/deadline 2026-05-08 and 2026-09-01/deadline 2026-09-10, both Completed, type Job application; application and employment conditions incl. average grade at least 8.00, ARIS register, same research programme as supervisor, full-time employment, dual tender+eVS applications, foreign-degree FAQ) and chunk 1 (read in this batch: separate registration per mentor; no age restriction, 4-year rule from second-cycle completion with 2022-01-01 anchor for 2026 and parental/health extensions; only second-level numerically graded obligations count toward the 8.00; fixed-term contract 4 years or 3 from year 2; salary grade 22 equating to 2,332.62 EUR gross with lunch/travel reimbursed and imbalance elimination to 2028; first call published every year on 15 March); Doctoral study page (source 3140). Encoding decisions: employment model with the single fetched gross figure kept textual (salary-grade/transitional), award NULL EUR month variable; the Slovenian-scale 8.00 kept textual, min_gpa NULL; status upcoming/not_published with both closed 2026 windows and the annual 15-March pattern in rounds. Scope discipline: ARIS-level call structure, non-UL organisations (e.g. Jozef Stefan Institute and its postgraduate school), any language condition and non-EU residence formalities were NOT fetched and are not asserted. university_id NULL because the University of Ljubljana has no row in universities yet (backlog: create university record/backlink). Do not revive retired 404. Rel 10.', true, NULL, NULL, 'EUR', 'month', 'variable');

