-- 5) us 274 sync (Universidad de Chile catalogue row)
UPDATE university_scholarships SET availability_status = 'available', funding_type = 'Merit-based', max_scholarship = 'Doctoral stipend CLP 900,000/month for 12 months (2026 cycle) plus full tuition (arancel) exemption; faculty rebates 50-100%', covers_tuition = true, covers_living_expenses = true, valued_aspect = 'In-programme merit for enrolled regular students (graduate-school nomination)', eligibility_notes = 'In-programme benefits for students already enrolled at the Universidad de Chile. The Beca de Doctorado UChile (CLP 900,000/month for 12 months in the 2026 cycle, plus full arancel exemption excluding matricula) requires being a regular 1st/2nd-year doctoral student in a CNA-accredited (6+ years) programme, having applied to the ANID national doctoral competition, holding no other funding, and nomination by your graduate school (max 2 per programme); it ends automatically if you win ANID. Faculty tuition rebates run 50-100 per cent under per-faculty windows; SYLFF-UChile (master in management and public policy) applies in December. The OAS, Nelson Mandela and AGCID entrance schemes are closed to applicants from Uzbekistan - plan as a pay-first destination. Resynced 2026-10-28 (Batch 30).', verification_status = 'verified', last_verified_at = now() WHERE id = 274;

